import{bounded,growthShape}from './growth-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=(x,y,s,size=17,c='#f8f5ef')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${size}">${esc(s)}</text>`;
const path=(d,c='#b8d0ce',w=3,extra='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" ${extra}/>`;
const circle=(x,y,r,c='#edac96')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f4ddbf" stroke-width="1.4"/>`;
let svgSequence=0;
export const growthSVG=(art,label)=>uniqueSVG(`<svg viewBox="0 0 560 420" role="img" aria-label="${esc(label)}"><defs><linearGradient id="growthStem" x1="0" x2="1"><stop stop-color="#577e78"/><stop offset=".5" stop-color="#b8c7ae"/><stop offset="1" stop-color="#6a8d7e"/></linearGradient><radialGradient id="growthFruit"><stop stop-color="#f9d5a6"/><stop offset="1" stop-color="#bd7664"/></radialGradient><marker id="growthArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5 0 10Z" fill="#c4d9d5"/></marker></defs>${art}</svg>`);
function uniqueSVG(svg){const id=++svgSequence;return svg.replaceAll('growthStem','growthStem'+id).replaceAll('growthFruit','growthFruit'+id).replaceAll('growthArrow','growthArrow'+id);}
const arrow=(d,c='#c4d9d5')=>path(d,c,2,'marker-end="url(#growthArrow)"');
function pill(x,y,w,label,active=false){return `<rect x="${x}" y="${y}" width="${w}" height="48" rx="17" fill="${active?'#896c67':'#365268'}" stroke="#b7cdca"/>`+text(x+w/2,y+29,label,16);}
export function feedbackFigure({progress=.5,state='',kind='feedback'}={}){let p=bounded(progress),n=Math.min(3,Math.floor(p*4)),a=text(280,30,kind==='adrenaline'||state==='adrenaline'||state==='substrates'?'Adrenaline: prepare for rapid action':'Thyroxine: a corrective control loop',22);if(kind==='adrenaline'||state==='adrenaline'||state==='substrates'){let labels=['Fear / stress','Adrenal glands','Adrenaline in blood','Heart / brain / muscles'];for(let i=0;i<4;i++){a+=pill(155,65+i*71,250,labels[i],n===i);if(i<3)a+=arrow(`M280 ${113+i*71}v22`);}a+=text(280,384,'Heart rate ↑ · oxygen and glucose delivery ↑',17);return growthSVG(a,'Adrenal glands release adrenaline during fear/stress. Heart rate and delivery of oxygen and glucose increase.');}
a+=pill(65,100,175,'Pituitary stimulation',n===1)+pill(330,100,150,'Thyroid',n===2)+pill(330,240,150,'Thyroxine',n===3);a+=arrow('M242 124h84')+arrow('M405 150v84')+path('M328 264H150V153','#edac96',3)+path('M135 153h30','#edac96',4)+text(150,294,'− inhibition',17)+text(280,341,state==='high'?'High level → less further stimulation':state==='low'?'Low level → less inhibition, more stimulation':'Return signal opposes the original change',17)+text(280,390,'Basal metabolic rate · growth · development',16);let pts=[[150,170],[280,124],[405,192],[255,264]],i=Math.min(3,Math.floor(p*4)),u=p*4-i,b=pts[i],c=pts[(i+1)%4];a+=circle(b[0]+(c[0]-b[0])*u,b[1]+(c[1]-b[1])*u,6);return growthSVG(a,'Simplified thyroxine negative feedback. Pituitary stimulates thyroid secretion; thyroxine inhibits further stimulation. Minus indicates inhibition.');}
export function tropismFigure(o={}){let {p,root,gravity,bend,auxinSide,response}=growthShape(o),a=text(280,28,gravity?(root?'Root: positive gravitropism':'Shoot: negative gravitropism'):'Shoot: positive phototropism',22),x=280+bend,y=112;
if(gravity){a+=arrow('M490 85v95')+text(490,203,'Gravity',15);a+=path('M100 210Q250 210 420 210','#d8d4c6',2,'stroke-dasharray="5 5"');a+=path(`M100 210Q250 210 ${400} ${210+bend}`,'url(#growthStem)',24);for(let j=0;j<7;j++){let q=j/6,xx=110+q*280,yy=210+bend*q*q;a+=path(`M${xx} ${yy-10}v20`,'#19384b',1.5);if(j<5)a+=circle(xx,yy+14,3,'#edac96');}a+=text(250,342,'Auxin accumulates on the lower side',16)+text(280,375,root?'Lower side inhibited → upper side grows more':'Lower side grows more → shoot curves up',15);}
else{let left=o.state!=='right',lampX=left?75:485;a+=circle(lampX,95,23,'#e8c595');for(let j=-1;j<2;j++)a+=arrow(`M${lampX+(left?32:-32)} ${95+j*22}h${left?55:-55}`);a+=text(lampX,53,'Light',15);a+=path('M80 330H480','#c5b8a2',2);a+=`<path d="M268 329Q270 215 ${x-12} ${y}L${x+12} ${y}Q290 215 292 329Z" fill="url(#growthStem)" stroke="#bed1bb" stroke-width="2"/>`;for(let j=1;j<8;j++){let q=j/8,xx=280+bend*q*q,yy=330-q*218;a+=path(`M${xx-10} ${yy}h20`,'#23473f',1.3);if(j%2)a+=circle(xx+(left?18:-18),yy,3,'#edac96');}a+=`<ellipse cx="${x-20}" cy="${y-7}" rx="29" ry="12" transform="rotate(-25 ${x-20} ${y-7})" fill="#a9bd9e"/><ellipse cx="${x+20}" cy="${y-7}" rx="29" ry="12" transform="rotate(25 ${x+20} ${y-7})" fill="#88aa9a"/>`;a+=text(280,369,'More elongation on the shaded '+auxinSide+' side',16);}
a+=text(280,406,'Growth/time/cells enlarged and simplified · not a measured rate',12);return growthSVG(a,`${gravity?'Gravity':'Light'} growth response. Auxin on ${auxinSide} side ${response} elongation in ${root?'root':'shoot'}. Unequal growth causes curvature.`);}
export function cuttingFigure({progress=0,kind='cutting'}={}){let p=bounded(progress),germ=kind==='germination',a=text(280,30,germ?'Gibberellin helps end dormancy':'Auxin: roots develop on a cutting',22);a+=`<rect x="145" y="270" width="270" height="90" rx="18" fill="#7f7163" fill-opacity=".65" stroke="#b6b2a2"/>`;if(germ){a+=`<ellipse cx="280" cy="260" rx="32" ry="22" fill="#caa67d" stroke="#e6d1ac" stroke-width="2"/>`;a+=path(`M280 253Q260 ${250-p*80} ${280-p*22} ${250-p*150}`,'url(#growthStem)',12);}else{a+=path('M280 270V110','url(#growthStem)',18)+`<ellipse cx="250" cy="144" rx="36" ry="14" transform="rotate(30 250 144)" fill="#9fbda8"/><ellipse cx="313" cy="185" rx="36" ry="14" transform="rotate(-30 313 185)" fill="#92afa2"/>`;if(p<.3)a+=circle(280,264,18,'#dbcfb7');}for(let i=0;i<5;i++){let end=280+(i-2)*p*26,y=270+p*(55+Math.abs(i-2)*7);a+=path(`M280 270Q${end} ${285+p*15} ${end} ${y}`,'#ecddbe',2.5);}a+=text(280,389,germ?'Water · oxygen · suitable temperature still needed':'Hormone signal + suitable growing conditions',16);return growthSVG(a,germ?'Simplified seed germination: seed coat and emerging root/shoot over compressed time.':'Cutting with roots developing from its base; auxin promotes rooting.');}
export function ripeningFigure({progress=0}={}){let p=bounded(progress),a=text(280,35,'Ethene: coordinate fruit ripening',23);for(let i=0;i<3;i++){let x=135+i*145;a+=`<circle cx="${x}" cy="225" r="54" fill="${p<.33?'#8fa88b':p<.66?'#d0ba7f':'url(#growthFruit)'}" stroke="#f4ddbf" stroke-width="2"/>`+path(`M${x} 171q-4-25 14-32`,'#9dbda6',6);for(let j=0;j<3;j++)a+=circle(x-32+j*28,100+Math.sin(p*8+j)*8,4,'#c2dad9');}a+=text(280,330,p<.33?'Earlier stage':p<.66?'Ripening progresses':'Later stage',20)+text(280,385,'Ethene also controls cell division · timing is symbolic',15);return growthSVG(a,'Fruit changes from earlier to later ripening stages. Ethene is a signal; colour alone does not define every fruit’s ripeness.');}
export function drawingFigure({shoot='',root='',seed='',bend='left'}={}){let dx=bend==='right'?65:bend==='straight'?0:-65,a=text(280,30,'Observation schematic · after 48 h',22)+text(80,88,'Light →',17)+arrow('M475 90v60')+text(475,175,'Gravity',15);a+=`<ellipse cx="280" cy="247" rx="26" ry="16" fill="#cdb08a"/>`+path(`M280 237Q280 160 ${280+dx} 108`,'#bfd0bb',10)+path('M280 260Q285 300 265 338','#e4d6b7',7);a+=path(`M${280+dx} 112L145 112H85`,'#ecdfce',1.5)+text(85,100,'A: '+(shoot||'…'),16)+path('M272 316H390L440 338','#ecdfce',1.5)+text(440,362,'B: '+(root||'…'),16)+path('M306 247H420','#ecdfce',1.5)+text(444,239,'C: '+(seed||'…'),16)+text(280,405,'Assembled schematic; practise freehand observed drawings too',12);return growthSVG(a,'Student labelled seedling. A: '+(shoot||'unlabelled')+'; B: '+(root||'unlabelled')+'; C: '+(seed||'unlabelled')+'. Light from left, gravity down.');}
export function evidenceFigure({kind='setup',state=''}={}){let a='';if(kind==='length'){a=text(280,35,'Original shoot measurements / mm',22);let rows=[['Seedling','Initial','Final','Increase'],['A','8','20','12'],['B','9','23','14'],['C','10','26','16']];for(let i=0;i<4;i++)for(let j=0;j<4;j++)a+=text(90+j*125,110+i*58,rows[i][j],18);a+=text(280,390,'Same starting points and method · compare increases',15);}
else if(kind==='biodiversity'||kind==='weed'||state==='weed'){a=text(280,35,'Crop benefit and ecological trade-offs',22)+text(280,115,'Less competition can benefit crops',19)+text(280,195,'Wild plants provide food and habitats',19)+text(280,275,'Original example: 20 → 15 wildflower species',18)+text(280,365,'Compare matched plots; examine other explanations',16);}
else if(kind==='culture'||state==='culture'){a=text(280,35,'Auxin supports plant tissue-culture growth',22)+`<ellipse cx="280" cy="235" rx="174" ry="80" fill="#627c79" stroke="#bfd4cf" stroke-width="3"/>`;for(let j=0;j<7;j++)a+=circle(220+j%3*55,210+Math.floor(j/3)*30,17,'#b4c5a4');a+=text(280,125,'Plant tissue + nutrient medium + hormones',16)+text(280,365,'Sterile controlled conditions · cells enlarged',16);}
else if(kind==='setup'||kind==='gravity-setup'){a=text(280,35,'Newly germinated seedlings',23);for(let i=0;i<2;i++){let x=155+i*250;a+=`<rect x="${x-85}" y="95" width="170" height="210" rx="18" fill="#34536b" stroke="#b8cfcb"/>`+path(kind==='gravity-setup'&&!i?`M${x-60} 220Q${x} 220 ${x+50} 200`:`M${x} 280Q${x} 205 ${x+(i?0:-30)} 160`,'#b9c8ab',9)+text(x,335,i?'Comparison':'Test',18);}a+=text(280,380,kind==='gravity-setup'?'Horizontal vs upright · control directional light':'One-sided vs even light · same species, water, time',15);}
else if(kind==='gibberellin'){a=text(280,45,'Gibberellin: three useful effects',23)+text(280,135,'End dormancy → germination',21)+text(280,230,'Promote flowering',21)+text(280,325,'Increase fruit size',21);}
else if(kind==='compare'){return tropismFigure({kind:'gravity',state:'root',progress:1});}
else if(kind==='logistics'){a=text(280,45,'Ripening, transport and sale',23)+pill(40,140,140,'Storage')+pill(210,140,140,'Transport')+pill(380,140,140,'Sale')+arrow('M182 164h24')+arrow('M352 164h24')+text(280,270,'Coordinate ripening with the intended arrival',18)+text(280,355,'Maturity and storage conditions still matter',17);}
else{let c=state==='culture',rip=state==='ripen';a=text(280,45,c?'Auxin in tissue culture':rip?'Ethene controls ripening':'Match hormone to developmental goal',22)+text(280,150,c?'Plant tissue + nutrients + suitable hormones':rip?'Food storage and transport':'Gibberellin: germination, flowering, fruit size',17)+text(280,250,c?'Sterile controlled conditions support growth':'Auxin: rooting, tissue culture, weed control',17)+text(280,350,'Effects and uses; molecular mechanisms not required',15);}return growthSVG(a,'Evidence diagram: '+kind+'. '+state);}
export function growthFigure(o={}){if(o.concealed)return growthSVG(text(280,200,'Predict, then reveal the growth response',22),'Outcome concealed until prediction');let k=o.kind||'light';if(['adrenaline','thyroid','feedback','control'].includes(k))return feedbackFigure(o);if(['light','shoot-gravity','root-gravity','gravity'].includes(k))return tropismFigure(o);if(k==='drawing')return drawingFigure(o);if(k==='cutting'||k==='germination')return cuttingFigure(o);if(k==='ripening')return ripeningFigure(o);return evidenceFigure(o);}
